impl Code {
    /// Every value, in discriminant order.
    pub fn values() -> impl ExactSizeIterator<Item = Code> + DoubleEndedIterator + Clone {
        CODE_VALUES.iter().copied()
    }

    /// The value with discriminant `i`.
    pub fn from_index(i: usize) -> Option<Code> {
        CODE_VALUES.get(i).copied()
    }

    /// The spec's name.
    pub fn name(self) -> &'static str {
        CODE_NAMES[self as usize]
    }

    /// The value with this spec name.
    pub fn from_name(name: &str) -> Option<Code> {
        CODE_BY_NAME
            .binary_search_by(|&i| CODE_NAMES[i as usize].cmp(name))
            .ok()
            .and_then(|k| Self::from_index(CODE_BY_NAME[k] as usize))
    }
}

