impl Mnemonic {
    /// Every value, in discriminant order.
    pub fn values() -> impl ExactSizeIterator<Item = Mnemonic> + DoubleEndedIterator + Clone {
        MNEMONIC_VALUES.iter().copied()
    }

    /// The value with discriminant `i`.
    pub fn from_index(i: usize) -> Option<Mnemonic> {
        MNEMONIC_VALUES.get(i).copied()
    }

    /// The spec's name.
    pub fn name(self) -> &'static str {
        MNEMONIC_NAMES[self as usize]
    }

    /// The value with this spec name.
    pub fn from_name(name: &str) -> Option<Mnemonic> {
        MNEMONIC_BY_NAME
            .binary_search_by(|&i| MNEMONIC_NAMES[i as usize].cmp(name))
            .ok()
            .and_then(|k| Self::from_index(MNEMONIC_BY_NAME[k] as usize))
    }
}

