impl Feature {
    /// Every value, in discriminant order.
    pub fn values() -> impl ExactSizeIterator<Item = Feature> + DoubleEndedIterator + Clone {
        FEATURE_VALUES.iter().copied()
    }

    /// The value with discriminant `i`.
    pub fn from_index(i: usize) -> Option<Feature> {
        FEATURE_VALUES.get(i).copied()
    }

    /// The spec's name.
    pub fn name(self) -> &'static str {
        FEATURE_NAMES[self as usize]
    }

    /// The value with this spec name.
    pub fn from_name(name: &str) -> Option<Feature> {
        FEATURE_BY_NAME
            .binary_search_by(|&i| FEATURE_NAMES[i as usize].cmp(name))
            .ok()
            .and_then(|k| Self::from_index(FEATURE_BY_NAME[k] as usize))
    }
}

